<template>
  <section class="ledger-page">
    <div class="page-heading ledger-heading"><div><div class="label">PERSONAL FINANCE / LEDGER</div><h1>账本 <span class="heading-slash">// OVERVIEW</span></h1><p class="muted">记录每一笔流动，月底自动对账。</p></div><div class="ledger-actions"><Button size="sm" variant="ghost" @click="aiOpen=true">自然语言记账</Button><Button size="sm" variant="ghost" @click="exportCsv">导出 CSV</Button><label class="ui-button variant-ghost size-sm import-label">导入 CSV / Excel<input type="file" accept=".csv,.xlsx,.xls,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" hidden @change="importFile" /></label><Button size="sm" variant="ghost" @click="layoutOpen=true">编辑首页</Button><Button @click="openCreate">记一笔 ＋</Button></div></div>
    <div class="ledger-status" :class="{offline:!online}"><span class="status-dot" :class="{online}"></span><span>{{ online ? '在线 · 自动同步' : '离线 · 已保存到本机' }}</span><span v-if="syncing">正在同步…</span><button v-if="!online" class="text-button" @click="loadData">重试</button></div>
    <div class="overview-toolbar"><div class="period-picker"><button @click="shiftMonth(-1)">‹</button><input v-model="selectedMonth" type="month" aria-label="选择账本月份"/><button @click="shiftMonth(1)">›</button></div><span>{{ monthLabel }} 首页总览</span></div>
    <div class="ledger-summary-grid">
      <Card v-show="widgetVisible('summary','income')" :style="{order:widgetOrder('summary','income')}"><template #header><div class="summary-label">本月收入</div></template><div class="summary-value income">¥{{ money(summary.income) }}</div><div class="summary-meta">{{ summary.incomeCount }} 笔流入</div></Card>
