      <Card v-show="widgetVisible('summary','net')" :style="{order:widgetOrder('summary','net')}"><template #header><div class="summary-label">本月结余</div></template><div class="summary-value" :class="summary.net>=0?'income':'expense'">¥{{ money(summary.net) }}</div><div class="summary-meta">收入 − 支出</div></Card>
      <Card v-show="widgetVisible('summary','asset')" :style="{order:widgetOrder('summary','asset')}"><template #header><div class="summary-label">总资产</div></template><div class="summary-value asset">¥{{ money(totalBalance) }}</div><div class="summary-meta">{{ accounts.length }} 个账户</div></Card>
    </div>
    <div class="home-widget-grid">
      <div v-show="widgetVisible('content','snapshot')" class="widget-full snapshot-grid" :style="{order:widgetOrder('content','snapshot')}"><div v-for="item in snapshots" :key="item.label" class="snapshot-item"><div><strong>{{ item.label }}</strong><small>{{ item.range }}</small></div><div><span class="income">+¥{{ money(item.income) }}</span><span class="expense">−¥{{ money(item.expense) }}</span><b :class="item.net>=0?'income':'expense'">结余 ¥{{ money(item.net) }}</b></div></div></div>
      <Card v-show="widgetVisible('content','daily')" class="chart-card widget-wide" :style="{order:widgetOrder('content','daily')}"><template #header><Head kicker="DAILY SPENDING" title="本月每日支出" :right="monthLabel"/></template><div ref="dailyRef" class="chart tall"/></Card>
      <Card v-show="widgetVisible('content','budget')" class="budget-overview widget-narrow" :style="{order:widgetOrder('content','budget')}"><template #header><Head kicker="BUDGET" title="本月支出与预算"><button class="text-button" @click="openBudget">设置</button></Head></template><div class="donut-wrap"><div ref="budgetRef" class="donut"/><div class="donut-label"><b>¥{{ money(budgetSummary.spent) }}</b><span>已支出</span></div></div><div class="budget-total"><span>预算 ¥{{ money(budgetSummary.budget) }}</span><b :class="budgetLeft<0?'budget-over':'income'">{{ budgetLeft<0?'超出':'剩余' }} ¥{{ money(Math.abs(budgetLeft)) }}</b></div><p v-if="!budgets.length" class="side-empty">设置分类预算后，在这里跟踪执行情况。</p></Card>
      <Card v-show="widgetVisible('content','category')" class="chart-card widget-wide" :style="{order:widgetOrder('content','category')}"><template #header><Head kicker="CATEGORY RANKING" :title="`${categoryScope==='month'?'本月':'本年'}支出分类`"><div class="seg"><button :class="{active:categoryScope==='month'}" @click="categoryScope='month'">本月</button><button :class="{active:categoryScope==='year'}" @click="categoryScope='year'">本年</button></div><div class="seg"><button :class="{active:categoryLevel==='primary'}" @click="categoryLevel='primary'">一级</button><button :class="{active:categoryLevel==='secondary'}" @click="categoryLevel='secondary'">二级</button></div></Head></template><div ref="categoryRef" class="chart medium"/></Card>
