    </div>
    <Sheet v-model:open="editorOpen" :title="editing?'编辑交易':'记一笔'"><form class="form" @submit.prevent="saveTransaction"><LedgerTransactionEditor :model="form" :accounts="accounts" :categories="categories" :kinds="kindOptions" :merchant-options="merchantOptions" :member-options="memberOptions" :project-options="projectOptions" :lock-kind="editing?.kind==='TRANSFER'"/><div class="form-footer"><Button type="button" variant="ghost" @click="editorOpen=false">取消</Button><Button type="submit">保存交易</Button></div></form></Sheet>
    <Drawer v-model:open="managerOpen" title="账户与分类"><div class="manager-tabs"><button :class="{active:managerTab==='accounts'}" @click="managerTab='accounts'">账户</button><button :class="{active:managerTab==='categories'}" @click="managerTab='categories'">分类</button></div><div v-if="managerTab==='accounts'" class="form"><div v-for="a in accounts" :key="a.id" class="manager-row"><span><b>{{a.name}}</b><small>{{accountType(a.accountType)}} · ¥{{money(a.balance)}}</small></span><button class="row-action" @click="removeAccount(a)">删除</button></div><form class="form" @submit.prevent="saveAccount"><input v-model="accountForm.name" class="ui-input" placeholder="账户名称" required/><select v-model="accountForm.accountType"><option value="cash">现金</option><option value="bank">银行卡</option><option value="card">信用卡</option><option value="wallet">电子钱包</option></select><input v-model="accountForm.openingBalance" class="ui-input" type="number" placeholder="期初余额"/><Button size="sm" type="submit">添加账户</Button></form></div><div v-else class="form"><div v-for="c in categories" :key="c.id" class="manager-row"><span><b>{{categoryPath(c)}}</b><small>{{c.kind==='INCOME'?'收入':'支出'}}</small></span><button class="row-action" @click="removeCategory(c)">删除</button></div><form class="form" @submit.prevent="saveCategory"><input v-model="categoryForm.name" class="ui-input" placeholder="分类名称" required/><select v-model="categoryForm.kind"><option value="EXPENSE">支出</option><option value="INCOME">收入</option></select><select v-model="categoryForm.parentId"><option value="">一级分类</option><option v-for="c in parents" :key="c.id" :value="String(c.id)">{{c.name}}</option></select><Button size="sm" type="submit">添加分类</Button></form></div></Drawer>
    <Sheet v-model:open="budgetOpen" title="预算设置"><p class="ai-intro">预算按月和支出分类统计，重复保存会更新对应分类。</p><div v-for="b in budgets" :key="b.id" class="manager-row"><span><b>{{b.category}}</b><small>¥{{money(b.spent)}} / ¥{{money(b.budget)}}</small></span><button class="row-action" @click="deleteBudget(b)">删除</button></div><form class="form" @submit.prevent="saveBudget"><label>月份<input v-model="budgetForm.monthKey" class="ui-input" type="month" required/></label><label>分类<select v-model="budgetForm.categoryId" required><option value="" disabled>选择支出分类</option><option v-for="c in expenses" :key="c.id" :value="String(c.id)">{{categoryPath(c)}}</option></select></label><label>金额<input v-model="budgetForm.amount" class="ui-input" type="number" min=".01" step=".01" required/></label><div class="form-footer"><Button type="button" variant="ghost" @click="budgetOpen=false">关闭</Button><Button type="submit">保存预算</Button></div></form></Sheet>
    <Sheet v-model:open="aiOpen" title="自然语言记账"><p class="ai-intro">说说刚刚发生的交易，助手会整理成可确认的记录。</p><textarea v-model="aiText" class="ui-textarea" placeholder="例如：今天午饭花了 32 元"/><Button class="ai-button" :disabled="aiLoading" @click="aiPreviewRequest">{{aiLoading?'识别中…':'识别交易'}}</Button><div v-if="aiPreview" class="ai-preview"><b :class="aiPreview.kind==='INCOME'?'income':'expense'">{{aiPreview.kind==='INCOME'?'+':'−'}}¥{{money(aiPreview.amount)}}</b><p>{{aiPreview.category}} · {{aiPreview.occurredOn}}</p><p>{{aiPreview.note}}</p><Button @click="confirmAi">确认记账</Button></div></Sheet>
    <Sheet v-model:open="layoutOpen" title="自定义首页"><p class="ai-intro">选择首页卡片，并调整它们的显示顺序。</p><div v-for="group in widgetGroups" :key="group.key" class="widget-settings"><div class="widget-settings-title">{{group.label}}</div><div v-for="(widget,index) in widgetConfig[group.key]" :key="widget.id" class="widget-setting-row"><button class="widget-visibility" :class="{on:widget.visible!==false}" :aria-label="widget.visible!==false?'移除卡片':'新增卡片'" @click="widget.visible=widget.visible===false">{{widget.visible!==false?'移除':'新增'}}</button><span>{{widget.label}}</span><button class="row-action" :disabled="index===0" @click="moveWidget(group.key,index,-1)">↑</button><button class="row-action" :disabled="index===widgetConfig[group.key].length-1" @click="moveWidget(group.key,index,1)">↓</button></div></div><div class="form-footer"><Button variant="ghost" @click="resetWidgets">恢复默认</Button><Button @click="layoutOpen=false">完成</Button></div></Sheet>
    <Dialog :open="Boolean(deleteTarget)" title="删除流水" @update:open="value=>{if(!value)deleteTarget=null}"><p class="transaction-delete-copy">删除后这笔流水将不再计入账本统计，确定继续吗？</p><template #footer><Button variant="ghost" :disabled="deleting" @click="deleteTarget=null">取消</Button><Button :disabled="deleting" @click="removeTransaction">{{deleting?'删除中…':'确认删除'}}</Button></template></Dialog>
  </section>
</template>

<script setup>
import { computed, h, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import * as echarts from 'echarts'
import { ElMessage } from 'element-plus'
import Card from '../components/ui/Card.vue'; import Button from '../components/ui/Button.vue'; import Table from '../components/ui/Table.vue'; import Sheet from '../components/ui/Sheet.vue'; import Drawer from '../components/ui/Drawer.vue'; import Dialog from '../components/ui/Dialog.vue'
import LedgerTransactionEditor from '../components/ledger/LedgerTransactionEditor.vue'
import { createLedgerSyncEngine } from '../../packages/sync-engine/src/index.js'
import { apiCreateLedgerAccount, apiCreateLedgerBudget, apiCreateLedgerCategory, apiCreateLedgerTransaction, apiDeleteLedgerAccount, apiDeleteLedgerBudget, apiDeleteLedgerCategory, apiDeleteLedgerTransaction, apiGetLedgerReports, apiImportLedgerCsv, apiImportLedgerExcel, apiLedgerAiConfirm, apiLedgerAiPreview, apiListLedgerAccounts, apiListLedgerCategories, apiListLedgerTransactions, apiPullLedgerSync, apiPushLedgerSync, apiUpdateLedgerTransaction } from '../api'

const Head={props:['kicker','title','right'],setup(props,{slots}){return()=>h('div',{class:'head'},[h('div',[h('div',{class:'kicker'},props.kicker),h('h2',props.title)]),h('div',{class:'head-right'},[slots.default?.(),props.right?h('span',props.right):null])])}}
const kindOptions=[{value:'EXPENSE',label:'支出',tone:'out'},{value:'INCOME',label:'收入',tone:'in'},{value:'TRANSFER',label:'转账',tone:'transfer'},{value:'BORROW_IN',label:'借入',tone:'in'},{value:'LEND_OUT',label:'借出',tone:'out'},{value:'COLLECT_DEBT',label:'收债',tone:'in'},{value:'REPAY_DEBT',label:'还债',tone:'out'}]
const incomeKinds=['INCOME','BORROW_IN','COLLECT_DEBT']; const expenseKinds=['EXPENSE','LEND_OUT','REPAY_DEBT']
const dateNow=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}; const today=dateNow(); const selectedMonth=ref(today.slice(0,7))
const accounts=ref([]),categories=ref([]),transactions=ref([]),optionTransactions=ref([]),reports=ref({}),annualReport=ref({}),budgets=ref([]),online=ref(navigator.onLine),syncing=ref(false),filter=ref('all'),categoryScope=ref('month'),categoryLevel=ref('primary')
const editorOpen=ref(false),editing=ref(null),managerOpen=ref(false),managerTab=ref('accounts'),budgetOpen=ref(false),aiOpen=ref(false),aiText=ref(''),aiPreview=ref(null),aiLoading=ref(false),layoutOpen=ref(false),deleteTarget=ref(null),deleting=ref(false)
const form=reactive({kind:'EXPENSE',amount:'',occurredOn:today,accountId:'',targetAccountId:'',categoryId:'',payee:'',member:'',project:'',note:''}); const accountForm=reactive({name:'',accountType:'cash',openingBalance:''}); const categoryForm=reactive({name:'',kind:'EXPENSE',parentId:''}); const budgetForm=reactive({monthKey:selectedMonth.value,categoryId:'',amount:''})
const widgetDefaults={summary:[{id:'income',label:'本月收入',visible:true},{id:'expense',label:'本月支出',visible:true},{id:'net',label:'本月结余',visible:true},{id:'asset',label:'总资产',visible:true}],content:[{id:'snapshot',label:'时间摘要',visible:true},{id:'daily',label:'本月每日支出',visible:true},{id:'budget',label:'本月支出与预算',visible:true},{id:'category',label:'支出分类',visible:true},{id:'budget-detail',label:'预算执行',visible:true},{id:'annual-bar',label:'年度收支柱状图',visible:true},{id:'annual-line',label:'年度收支走势',visible:true},{id:'calendar',label:'月度记账日历',visible:true},{id:'transactions',label:'最近交易',visible:true},{id:'accounts',label:'账户',visible:true}]}
const widgetConfig=ref(loadWidgetConfig()); const widgetGroups=[{key:'summary',label:'汇总卡片'},{key:'content',label:'内容卡片'}]
const dailyRef=ref(null),categoryRef=ref(null),barRef=ref(null),lineRef=ref(null),budgetRef=ref(null),chartMap=new Map(); let themeObserver; const weekdays=['日','一','二','三','四','五','六']; const selectedYear=computed(()=>selectedMonth.value.slice(0,4)); const monthLabel=computed(()=>`${selectedYear.value} 年 ${Number(selectedMonth.value.slice(5))} 月`); const monthStart=computed(()=>`${selectedMonth.value}-01`); const monthEnd=computed(()=>endOfMonth(selectedMonth.value)); const yearStart=computed(()=>`${selectedYear.value}-01-01`); const yearEnd=computed(()=>`${selectedYear.value}-12-31`)
const range=(d,a,b)=>String(d||'')>=a&&String(d||'')<=b; const sum=rows=>{const incomeRows=rows.filter(x=>incomeKinds.includes(x.kind)),expenseRows=rows.filter(x=>expenseKinds.includes(x.kind)),income=incomeRows.reduce((n,x)=>n+Number(x.amount||0),0),expense=expenseRows.reduce((n,x)=>n+Number(x.amount||0),0);return{income,expense,net:income-expense,incomeCount:incomeRows.length,expenseCount:expenseRows.length}}; const monthItems=computed(()=>transactions.value.filter(x=>range(x.occurredOn,monthStart.value,monthEnd.value))); const summary=computed(()=>sum(monthItems.value)); const totalBalance=computed(()=>accounts.value.reduce((n,x)=>n+Number(x.balance||0),0)); const expenses=computed(()=>categories.value.filter(x=>x.kind==='EXPENSE'&&x.parentId)); const parents=computed(()=>categories.value.filter(x=>x.kind===categoryForm.kind&&!x.parentId)); const filteredTransactions=computed(()=>transactions.value.filter(x=>filter.value==='all'||(filter.value==='INCOME'?incomeKinds:expenseKinds).includes(x.kind)).slice(0,12));
const uniqueOptions=field=>[...new Set(optionTransactions.value.map(item=>String(item[field]||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN')); const merchantOptions=computed(()=>uniqueOptions('payee')); const memberOptions=computed(()=>uniqueOptions('member')); const projectOptions=computed(()=>uniqueOptions('project')); const amountClass=kind=>incomeKinds.includes(kind)?'income':expenseKinds.includes(kind)?'expense':''; const amountSign=kind=>incomeKinds.includes(kind)?'+':expenseKinds.includes(kind)?'−':''
const dailyRows=computed(()=>Array.from({length:Number(monthEnd.value.slice(-2))},(_,i)=>{const date=`${selectedMonth.value}-${String(i+1).padStart(2,'0')}`;return{date,...sum(monthItems.value.filter(x=>x.occurredOn===date))}})); const budgetSummary=computed(()=>reports.value.budgetSummary||reports.value.budget_summary||{budget:budgets.value.reduce((n,x)=>n+Number(x.budget||0),0),spent:budgets.value.reduce((n,x)=>n+Number(x.spent||0),0)}); const budgetLeft=computed(()=>Number(budgetSummary.value.budget||0)-Number(budgetSummary.value.spent||0)); const rank=computed(()=>{const map=new Map; for(const x of ((categoryScope.value==='month'?reports.value:annualReport.value).categories||[]).filter(x=>x.kind==='EXPENSE')){const key=categoryLevel.value==='primary'?(x.parent_category||x.parentCategory||x.category||'未分类'):(x.category||'未分类');map.set(key,(map.get(key)||0)+Number(x.amount||0))}return[...map].map(([name,amount])=>({name,amount})).sort((a,b)=>b.amount-a.amount).slice(0,8)}); const months=computed(()=>{const map=new Map((annualReport.value.monthly||[]).map(x=>[x.month,x]));return Array.from({length:12},(_,i)=>{const x=map.get(`${selectedYear.value}-${String(i+1).padStart(2,'0')}`)||{},income=Number(x.income||0),expense=Number(x.expense||0);return{label:`${i+1}月`,income,expense,net:income-expense}})}); const weekStart=()=>{const d=new Date(`${today}T00:00:00`);d.setDate(d.getDate()-(d.getDay()||7)+1);return d.toISOString().slice(0,10)}; const snapshots=computed(()=>[{label:'今天',range:today.replaceAll('-','.'),...sum(transactions.value.filter(x=>x.occurredOn===today))},{label:'本周',range:`${weekStart().slice(5).replace('-','.')} - ${today.slice(5).replace('-','.')}`,...sum(transactions.value.filter(x=>range(x.occurredOn,weekStart(),today)))},{label:'本年',range:`${selectedYear.value}.01.01 - ${selectedYear.value}.12.31`,...sum(transactions.value.filter(x=>range(x.occurredOn,yearStart.value,yearEnd.value)))}]); const calendarCells=computed(()=>{const blank=new Date(`${selectedMonth.value}-01T00:00:00`).getDay(),days=dailyRows.value.map(x=>({key:x.date,day:+x.date.slice(-2),income:x.income,expense:x.expense,today:x.date===today}));return[...Array.from({length:blank},(_,i)=>({key:`a${i}`})),...days,...Array.from({length:(7-(blank+days.length)%7)%7},(_,i)=>({key:`b${i}`}))]})
