function init(key,el){if(!el||!el.clientWidth||!el.clientHeight)return;chartMap.get(key)?.dispose();const c=echarts.init(el);chartMap.set(key,c);return c} async function draw(){await nextTick();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const s=getComputedStyle(document.documentElement),text=s.getPropertyValue('--ink2').trim()||'#49505c',line=s.getPropertyValue('--line').trim()||'#e2ded4',accent=s.getPropertyValue('--accent').trim()||'#0f5132',up=s.getPropertyValue('--up').trim()||'#067647',down=s.getPropertyValue('--down').trim()||'#b42318',tip={trigger:'axis',valueFormatter:v=>`¥${money(v)}`};const axis={axisLine:{lineStyle:{color:line}},axisLabel:{color:text,fontSize:10}};init('daily',dailyRef.value)?.setOption({grid:{left:12,right:16,top:16,bottom:24,containLabel:true},tooltip:tip,xAxis:{type:'category',data:dailyRows.value.map(x=>x.date.slice(-2)),...axis},yAxis:{type:'value',axisLabel:{color:text,fontSize:10},splitLine:{lineStyle:{color:line,type:'dashed'}}},series:[{name:'支出',type:'line',smooth:true,symbol:'circle',symbolSize:5,data:dailyRows.value.map(x=>x.expense),lineStyle:{color:up,width:2},areaStyle:{color:`${up}1f`}}]}); const r=[...rank.value].reverse();init('category',categoryRef.value)?.setOption({grid:{left:12,right:28,top:14,bottom:12,containLabel:true},tooltip:tip,xAxis:{type:'value',axisLabel:{color:text,fontSize:10},splitLine:{lineStyle:{color:line,type:'dashed'}}},yAxis:{type:'category',data:r.map(x=>x.name),axisTick:{show:false},axisLine:{show:false},axisLabel:{color:text,fontSize:11}},series:[{type:'bar',data:r.map(x=>x.amount),barMaxWidth:18,itemStyle:{color:up,borderRadius:[0,3,3,0]}}]});const opts={grid:{left:12,right:12,top:30,bottom:24,containLabel:true},tooltip:tip,legend:{data:['收入','支出','结余'],textStyle:{color:text,fontSize:10},right:0,top:0},xAxis:{type:'category',data:months.value.map(x=>x.label),...axis},yAxis:{type:'value',axisLabel:{color:text,fontSize:10},splitLine:{lineStyle:{color:line